// Analyze dungeon statistics and identify issues
const dungeons = $node["Get All Dungeons"].json.dungeons;

const analysis = {
  totalDungeons: dungeons.length,
  averageDifficulty: 0,
  mostComplexDungeon: null,
  oldestDungeon: null,
  generationIssues: [],
  performanceMetrics: {
    averageGenerationTime: 0,
    slowestGeneration: null
  }
};

// Calculate metrics
if (dungeons.length > 0) {
  // Average difficulty
  const totalDifficulty = dungeons.reduce((sum, d) => sum + (d.statistics?.difficultyRating || 1), 0);
  analysis.averageDifficulty = Math.round((totalDifficulty / dungeons.length) * 10) / 10;

  // Most complex dungeon
  analysis.mostComplexDungeon = dungeons.reduce((most, current) => 
    (current.statistics?.totalRooms || 0) > (most.statistics?.totalRooms || 0) ? current : most
  , dungeons[0]);

  // Oldest dungeon
  analysis.oldestDungeon = dungeons.reduce((oldest, current) => 
    new Date(current.timestamp || 0) < new Date(oldest.timestamp || Date.now()) ? current : oldest
  , dungeons[0]);

  // Performance metrics
  const generationTimes = dungeons.map(d => d.generationTime || 0).filter(t => t > 0);
  if (generationTimes.length > 0) {
    analysis.performanceMetrics.averageGenerationTime = Math.round(
      generationTimes.reduce((sum, time) => sum + time, 0) / generationTimes.length
    );

    const maxTime = Math.max(...generationTimes);
    analysis.performanceMetrics.slowestGeneration = dungeons.find(d => d.generationTime === maxTime);
  }

  // Check for issues
  dungeons.forEach((dungeon, index) => {
    if (dungeon.statistics?.difficultyRating > 8) {
      analysis.generationIssues.push({
        type: 'high_difficulty',
        dungeonId: dungeon.id,
        difficulty: dungeon.statistics.difficultyRating,
        message: `Very high difficulty rating: ${dungeon.statistics.difficultyRating}/10`
      });
    }

    if (dungeon.generationTime && dungeon.generationTime > 30000) {
      analysis.generationIssues.push({
        type: 'slow_generation',
        dungeonId: dungeon.id,
        generationTime: dungeon.generationTime,
        message: `Slow generation: ${dungeon.generationTime}ms`
      });
    }

    if (dungeon.statistics?.totalRooms === 0) {
      analysis.generationIssues.push({
        type: 'no_rooms',
        dungeonId: dungeon.id,
        message: 'Dungeon has no rooms'
      });
    }
  });
}

return { json: analysis };

// Check if any critical issues need attention
const analysis = $node["Analyze Dungeon Statistics"].json;

const alerts = [];

// Check for critical issues
if (analysis.generationIssues.length > 0) {
  const criticalIssues = analysis.generationIssues.filter(issue => 
    issue.type === 'no_rooms' || 
    issue.type === 'slow_generation'
  );

  if (criticalIssues.length > 0) {
    alerts.push({
      level: 'critical',
      title: 'Critical Dungeon Generation Issues',
      message: `${criticalIssues.length} critical issues detected`,
      details: criticalIssues
    });
  }
}

// Check performance warnings
if (analysis.performanceMetrics.averageGenerationTime > 20000) {
  alerts.push({
    level: 'warning',
    title: 'Slow Generation Performance',
    message: `Average generation time: ${analysis.performanceMetrics.averageGenerationTime}ms`,
    details: {
      averageTime: analysis.performanceMetrics.averageGenerationTime,
      slowestGeneration: analysis.performanceMetrics.slowestGeneration
    }
  });
}

// Check for high average difficulty
if (analysis.averageDifficulty > 7) {
  alerts.push({
    level: 'info',
    title: 'High Average Difficulty',
    message: `Average difficulty rating: ${analysis.averageDifficulty}/10`,
    details: {
      averageDifficulty: analysis.averageDifficulty,
      recommendation: 'Consider adjusting difficulty parameters'
    }
  });
}

return { json: { alerts, analysis } };

// Send alerts for each issue found
const alerts = $node["Check for Alerts"].json.alerts;
const alertMessages = [];

alerts.forEach(alert => {
  let message = `🚨 ${alert.title}\n`;
  message += `Level: ${alert.level}\n`;
  message += `Message: ${alert.message}\n`;

  if (alert.details) {
    message += `Details: ${JSON.stringify(alert.details, null, 2)}`;
  }

  alertMessages.push({
    message,
    level: alert.level,
    timestamp: new Date().toISOString()
  });
});

return { json: alertMessages };

